import re
from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class LncelParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cell_ent = self.enb_ent_config['cells'][self.cell_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if self.cell_ent['is_fdd']:
            self.set_fdd_params()
        else:
            self.set_tdd_params()

        self.set_chBw_dependencies()
        self.set_parameter('lcrId', self.mo_num)
        self.set_parameter('phyCellId', self.cell_ent['pci'])
        self.set_parameter('tac', self.cell_ent['tac'])
        self.set_parameter('administrativeState', self.cell_ent.get('administrative_state', 'unlocked'))
        self.set_parameter('pMax', self.cell_ent['p_max'])
        self.set_parameter('maxNumUeProactiveUl', 10)
        self.set_parameter('maxNumUeProactiveUlNonTxSkip', 10)

        if execution_config['release'] >= 24.2:
            self.set_parameter('actMicroDtx', 'false')

    def set_fdd_params(self):
        self.set_parameter('cellTechnology', 'FDD')
        self.set_parameter('maxPeriodicCqiIncrease', 15)
        self.set_parameter('ttibAltUlPrbThreshold', 0)
        self.set_parameter('actInactiveTimeForwarding', 'false')

    def set_tdd_params(self):
        self.set_parameter('cellTechnology', 'TDD')

    def set_chBw_dependencies(self):
        if 'ch_bw' in self.cell_ent:
            ch_bw = float(re.match(r'(.*) MHz', self.cell_ent['ch_bw']).group(1))
            if ch_bw <= 5:
                cqiAperEnable = 'false'
                iniPrbsUl = 6
                pdcchAggMsg4 = 4
            else:
                cqiAperEnable = 'true'
                iniPrbsUl = 10
                pdcchAggMsg4 = 8

            self.set_parameter('cqiAperEnable', cqiAperEnable)
            self.set_parameter('iniPrbsUl', iniPrbsUl)
            self.set_parameter('pdcchAggMsg4', pdcchAggMsg4)
